window.AUTH=window.AUTH||{};window.AUTH["19-67"]={"d":"19-67","id":"2019/19-67","n":"United States v. Sineneng-Smith","briefs":[{"k":"petitioner","label":"Brief of petitioner United States","date":"2019-12-02","url":"https://www.supremecourt.gov/DocketPDF/19/19-67/124161/20191202184433375_19-67tsUnitedStates.pdf","side":"pet","n":79},{"k":"respondent","label":"Brief of respondent Evelyn Sineneng-Smith","date":"2020-01-15","url":"https://www.supremecourt.gov/DocketPDF/19/19-67/128782/20200115171844509_19-67%20bs.pdf","side":"res","n":64},{"k":"reply","label":"Reply of petitioner United States","date":"2020-02-14","url":"https://www.supremecourt.gov/DocketPDF/19/19-67/133145/20200214155731841_19-67rbUnitedStates.pdf","side":"pet","n":50}],"opinion":"https://www.supremecourt.gov/opinions/preliminaryprint/590US1PP_web.pdf#page=387","tr":true,"items":[{"t":"case","label":"Apprendi v. New Jersey","cite":"530 U.S. 466","y":2000,"id":"1999/99-478","sc":1,"sum":"The Court held that the Due Process Clause requires that any fact that increases the penalty for a crime beyond the prescribed statutory maximum, other than the fact of a prior conviction, must be submitted to a jury and proved beyond a reasonable doubt.","sumSrc":"Oyez","by":{"0":"36, 40"}},{"t":"case","label":"Building Serv. Emps. Int’l Union v. Gazzam","cite":"339 U.S. 532","y":1950,"id":"scdb/1949-076","sc":1,"sum":"In a state whose public policy is that employers shall not coerce their employees' choice of a bargaining representative, a state court injunction against peaceful picketing by a labor union for the particular purpose of compelling an employer to sign a contract which would coerce his employees' choice of a bargaining representative does not violate the right of free speech guaranteed by the First and Fourteenth …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"43","2":"18, 19"}},{"t":"case","label":"Clark v. Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"sum":"The Court said the requirement that immigrants be detained no longer than reasonably necessary for deportation applied to both admissible and inadmissible immigrants. Because readmission to Cuba was unforeseeable, the detentions of Martinez and Benitez were unreasonable.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Connecticut Nat’l Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"sum":"An interlocutory order issued by a district court sitting as a court of appeals in bankruptcy is appealable under the unambiguous language of 28 U. S. C. § 1292. That section provides for review in the courts of appeals, in certain circumstances, of \"[i]nterlocutory orders of the district courts,\" and does not limit such review to orders issued by district courts sitting as bankruptcy trial courts rather than …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38"}},{"t":"case","label":"Cox v. Louisiana","cite":"379 U.S. 559","y":1965,"id":"1964/49","sc":1,"op":1,"sum":"The Court determined whether a conviction based on a Louisiana statute prohibiting picketing before a courthouse violated the defendant's rights to free speech and assembly under the First and Fourteenth Amendments.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"Elonis v. United States","cite":"135 S. Ct. 2001","y":2015,"id":"2014/13-983","sc":1,"sum":"The Court found that in order to violate the transmission of threats provision, the threat requires both an objective and subjective intent.","sumSrc":"Oyez","by":{"0":"25","2":"21"}},{"t":"case","label":"Ford v. State","cite":"262 P.3d 1123","y":2011,"court":"Nev.","url":"https://www.courtlistener.com/c/P.3d/262/1123/","sum":"Construing prohibition on soliciting prostitution not to reach “abstract advocacy”.","sumSrc":"brief:0","by":{"0":"34"}},{"t":"case","label":"Fox v. Washington","cite":"236 U.S. 273","y":1915,"id":"scdb/1914-215","sc":1,"sum":"Where the highest court of the State, in overruling a demurrer, affirmed that the Constitution of the United States guaranteed freedom of speech, but held the'statute on which the indictment was based valid in that respect and also that it was not bad for uncertainty, citing cases decided by this court as authority, this court may gather that rights under the Federal Constitution were relied on apart from the …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"31"}},{"t":"case","label":"Giboney v. Empire Storage & Ice Co.","cite":"336 U.S. 490","y":1949,"id":"scdb/1948-056","sc":1,"sum":"The state law, as construed and applied in this case, does not violate the Federal Constitution, and the judgment is affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31, 32","1":"38","2":"19"}},{"t":"case","label":"Grant Bros. Constr. Co. v. United States","cite":"232 U.S. 647","y":1914,"id":"scdb/1913-204","sc":1,"sum":"An action by the United States to recover penalties under the Alien Contract Labor Law is civil and attended with the usual incidents of a civil action. United States v. Regan, ante, p. 37.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"Helvering v. Mitchell","cite":"303 U.S. 391","y":1938,"id":"scdb/1937-140","sc":1,"sum":"That an acquittal of a charge of wilful attempt to evade, under § 146 (b), does not bar assessment and collection of the 50% addition prescribed by § 293 (b)..397 et seq. The doctrine of res judicata is inapplicable because of the difference in quantum of proof in civil and criminal cases; the acquittal was merely an adjudication that the proof was not sufficient to overcome all reasonable doubt of guilt. P. 397. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"43"}},{"t":"case","label":"Hooper v. California","cite":"155 U.S. 648","y":1895,"id":"scdb/1894-069","sc":1,"sum":"Section 439 of the Penal Code of California, making it a misdemeanor for a person in that State to procure insurance for a resident in the State from an insurance company not incorporated under its laws and which had not filed the bond required by the laws of the State relative to insurance, is not a regulation of commerce, and does not couflict with the Constitution of the United States, when enforced against the …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"27"}},{"t":"case","label":"Hudson v. United States","cite":"522 U.S. 93","y":1997,"id":"1997/96-976","sc":1,"sum":"The Court held that the Double Jeopardy Clause does not apply to non-criminal penalties, even if the purpose of the penalty is to punish the offenders and deter future offenders. Since the first punishment handed down by the OCC - a Federal Banking Agency, not a court - was not a criminal punishment, the subsequent indictments were upheld.","sumSrc":"Oyez","by":{"0":"43"}},{"t":"case","label":"INS v. St. Cyr","cite":"533 U.S. 289","y":2001,"id":"2000/00-767","sc":1,"sum":"The Court held that habeas jurisdiction was not repealed by AEDPA and IIRIRA.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"International Bhd. of Elec. Workers v. NLRB","cite":"341 U.S. 694","y":1951,"id":"scdb/1950-096","sc":1,"sum":"This finding and the order are sustained. See Labor Board v. Denver Building Trades Council, ante, p. 675.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"34, 42","1":"18, 39","2":"4"}},{"t":"case","label":"International Bhd. of Teamsters v. Vogt, Inc.","cite":"354 U.S. 284","y":1957,"id":"1956/79","sc":1,"sum":"The judgment is affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42","1":"39"}},{"t":"case","label":"Kleindienst v. Mandel","cite":"408 U.S. 753","y":1972,"id":"1971/71-16","sc":1,"sum":"The Court held that the First Amendment did not obligate Kleindienst to grant a waiver to Mandel.","sumSrc":"Oyez","by":{"0":"4"}},{"t":"case","label":"Lees v. United States","cite":"150 U.S. 476","y":1893,"id":"scdb/1893-058","sc":1,"sum":"A district court of the United States has jurisdiction over an action to recover a penalty imposed for a violation of the act of February 26, 1885, '23 Stat. 332, c. 164, “to prohibit the importation and migration of foreigners and aliens under contract or agreement to perform labor in the United States, its Territories, and the District of Columbia.”","sumSrc":"Headnote (U.S. Reports)","by":{"0":"5, 23, 43","1":"31"}},{"t":"case","label":"Los Angeles Police Dep’t v. United Reporting Publ’g Corp.","cite":"528 U.S. 32","y":1999,"id":"1999/98-678","sc":1,"op":1,"sum":"The Court held that the amended statute was not an abridgment of anyone's right to engage in speech, commercial or otherwise, but simply a law regulating access to information in the hands of law enforcement agencies.","sumSrc":"Oyez","by":{"0":"15, 17, 28","2":"16, 17"}},{"t":"case","label":"Loughrin v. United States","cite":"573 U.S. 351","y":2014,"id":"2013/13-316","sc":1,"sum":"The Court held that, to find someone guilty of bank fraud, only one of the two bank fraud statutes must be met, not both.","sumSrc":"Oyez","by":{"0":"39","1":"23","2":"6"}},{"t":"case","label":"Marx v. General Revenue Corp.","cite":"568 U.S. 371","y":2013,"id":"2012/11-1175","sc":1,"sum":"The Court held that the Federal Rules of Civil Procedure awards costs to the prevailing party unless a statute explicitly states otherwise.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"Members of the City Council v. Taxpayers for Vincent","cite":"466 U.S. 789","y":1984,"id":"1983/82-975","sc":1,"sum":"Section 28.04 of the Los Angeles Municipal Code prohibits the posting of signs on public property. Appellee Taxpayers for Vincent, a group of supporters of a candidate for election to the Los Angeles City Council, entered into a contract with appellee Candidates' Outdoor Graphics Service (COGS) to fabricate and post signs with the candidate's name on them. COGS produced cardboard signs and attached them to utility …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17, 18, 28, 33","1":"2, 37","2":"9"}},{"t":"case","label":"New York v. Ferber","cite":"458 U.S. 747","y":1982,"id":"1981/81-55","sc":1,"op":2,"sum":"In the Court's first examination of a statute specifically targeted against child pornography, it found that the state's interest in preventing sexual exploitation of minors was a compelling \"government objective of surpassing importance.\" The law was carefully drawn to protect children from the mental, physical, and sexual abuse associated with pornography while not violating the First Amendment.","sumSrc":"Oyez","by":{"0":"16, 17, 26"}},{"t":"case","label":"Pittsburgh Press Co. v. Pittsburgh Comm’n on Human Relations","cite":"413 U.S. 376","y":1973,"id":"1972/72-419","sc":1,"op":2,"ar":2,"sum":"The Court held that an ordinance that forbids newspapers to advertise employment opportunities in gender-designated columns does not violate the freedom of press guaranteed by the First Amendment.","sumSrc":"Oyez","by":{"0":"41","1":"38, 39","2":"19"}},{"t":"case","label":"Rosemond v. United States","cite":"572 U.S. 65","y":2014,"id":"2013/12-895","sc":1,"ar":1,"sum":"The Court held that the state must prove that an individual intended to commit or assist in committing a firearm-related offense in a drug trafficking case to be charged with offenses related to the firearm.","sumSrc":"Oyez","by":{"0":"26","2":"5"}},{"t":"case","label":"State v. Ferguson","cite":"264 P.3d 575","y":2011,"court":"Wash. Ct. App.","url":"https://www.courtlistener.com/c/P.3d/264/575/","sum":"Construing aiding-and-abetting statute not to “forbid the mere advocacy of law violation,” and rejecting overbreadth challenge.","sumSrc":"brief:0","by":{"0":"34"}},{"t":"case","label":"United States v. Aguilar","cite":"515 U.S. 593","y":1995,"id":"1994/94-270","sc":1,"sum":"The Supreme Court held that making false statements to an FBI agent who may or may not testify at trial is not sufficient to support a conviction for obstruction of justice. Aguilar’s conviction for disclosing a wiretap was proper, however, because the statute does not require that the wiretap is currently in force. The First Amendment did not require excluding expired wiretaps from the statute either.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"United States v. Alvarez","cite":"567 U.S. 709","y":2012,"id":"2011/11-210","sc":1,"sum":"The Court found that the Stolen Valor Act violated the First Amendment.","sumSrc":"Oyez","by":{"0":"39","1":"38, 41"}},{"t":"case","label":"United States v. Booker","cite":"543 U.S. 220","y":2005,"id":"2004/04-104","sc":1,"sum":"The Court held that the Sentencing Guidelines, where they allow judges to enhance sentences using facts not reviewed by juries, violated the Sixth Amendment right to trial by jury. The sentences of Booker and Fanfan, based partly on facts determined only by judges, were therefore unconstitutional.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"United States v. Castillo-Felix","cite":"539 F.2d 9","y":1976,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/539/9/","by":{"0":"30"}},{"t":"case","label":"United States v. Evans","cite":"333 U.S. 483","y":1948,"id":"scdb/1947-057","sc":1,"sum":"1. Section 8 of the Immigration Act of 1917 does not make it a punishable offense to conceal or harbor aliens not entitled to enter or reside in the United States, in view of the ambiguity in the statute as to the scope of the offense and as to the penalty which Congress intended to prescribe,","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40"}},{"t":"case","label":"United States v. Fujii","cite":"301 F.3d 535","y":2002,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/301/535/","by":{"0":"30"}},{"t":"case","label":"United States v. He","cite":"245 F.3d 954","y":2001,"url":"https://www.courtlistener.com/c/F.3d/245/954/","by":{"0":"25, 30"}},{"t":"case","label":"United States v. Henderson","cite":"857 F. Supp. 2d 191","y":2012,"court":"D. Mass.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/857/191/","ar":4,"by":{"0":"33","1":"13, 34, 35","2":"9, 10"}},{"t":"case","label":"United States v. Hoy","cite":"330 U.S. 724","y":1947,"id":"scdb/1946-081","sc":1,"sum":"1. Section 5 (g) of the Farm Labor Supply Appropriation Act of 1944 does not except agricultural laborers from the provision of § 5 of the Immigration Act of 1917 making it a criminal offense to induce to migrate to the United States as contract laborers aliens who are not entitled to enter the United States under the 1917 Act or any other law of the United States.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24","2":"3"}},{"t":"case","label":"United States v. Kalu","cite":"791 F.3d 1194","y":2015,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/791/1194/","by":{"0":"25, 30"}},{"t":"case","label":"United States v. Martinez","cite":"900 F.3d 721","y":2018,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/900/721/","by":{"0":"29"}},{"t":"case","label":"United States v. Ndiaye","cite":"434 F.3d 1270","y":2006,"url":"https://www.courtlistener.com/c/F.3d/434/1270/","by":{"0":"29"}},{"t":"case","label":"United States v. Nguyen","cite":"73 F.3d 887","y":1995,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/73/887/","by":{"0":"25"}},{"t":"case","label":"United States v. Okatan","cite":"728 F.3d 111","y":2013,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/728/111/","by":{"0":"30"}},{"t":"case","label":"United States v. Oloyede","cite":"982 F.2d 133","y":1993,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/982/133/","by":{"0":"29"}},{"t":"case","label":"United States v. Raines","cite":"362 U.S. 17","y":1960,"id":"1959/64","sc":1,"op":2,"sum":"Under authority of R. S. § 2004, as amended by the Civil Rights Act of 1957, the Attorney General bronght this civil action on behalf of the United States in a Federal District Court to enjoin certain public officials of the State of Georgia from discriminating against Negro citizens who desired to register to vote in elections in Georgia. 'The District Court dismissed the complaint on the ground that subsection …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16"}},{"t":"case","label":"United States v. Stevens","cite":"559 U.S. 460","y":2010,"id":"2009/08-769","sc":1,"op":1,"sum":"The Court ruled that 18 U.S.C. Section 48 was unconstitutional under the Free Speech Clause of the First Amendment.","sumSrc":"Oyez","by":{"0":"32, 37","1":"passim","2":"18"}},{"t":"case","label":"United States v. Tracy","cite":"456 Fed. Appx. 267","y":2011,"court":"4th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./456/267/","by":{"0":"29, 30"}},{"t":"case","label":"United States v. Williams","cite":"553 U.S. 285","y":2008,"id":"2007/06-694","sc":1,"op":3,"ar":4,"sum":"Held that the statute was not overly broad as written. Justice Scalia noted specifically that offers to engage in illegal transactions are categorically excluded from First Amendment protection, and he characterized the speech of an individual claiming to be in possession of child pornography in this category of unprotected speech.","sumSrc":"Oyez","by":{"0":"passim","1":"21, 22, 38, 39, 47","2":"passim"}},{"t":"case","label":"United States v. Yoshida","cite":"303 F.3d 1145","y":2002,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/303/1145/","by":{"0":"30"}},{"t":"case","label":"United States v. Zayas-Morales","cite":"685 F.2d 1272","y":1982,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/685/1272/","by":{"0":"25"}},{"t":"case","label":"Virginia v. Hicks","cite":"539 U.S. 113","y":2003,"id":"2002/02-371","sc":1,"sum":"The Court held that the RRHA's trespass policy is not facially invalid under the First Amendment's overbreadth doctrine.","sumSrc":"Oyez","by":{"0":"17, 18, 33","1":"3, 16, 37"}},{"t":"case","label":"Washington State Grange v. Washington State Republican Party","cite":"552 U.S. 442","y":2008,"id":"2007/06-713","sc":1,"op":2,"sum":"The Court reversed the Ninth Circuit's ruling and held the party affiliation provision constitutional. Writing for the majority, Justice Clarence Thomas explained that the state law never referred to the candidates as nominees of any particular party.","sumSrc":"Oyez","by":{"0":"16, 28","2":"21"}},{"t":"law","label":"Pub. L. No. 104-208","url":"https://www.govinfo.gov/link/plaw/104/public/208","by":{"0":"7","2":"7"}},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","by":{"0":"5"}},{"t":"usc","label":"8 U.S.C. § 1182","url":"https://www.law.cornell.edu/uscode/text/8/1182","subs":["(a)(5)(A)"],"by":{"0":"7"}},{"t":"usc","label":"8 U.S.C. § 1255","url":"https://www.law.cornell.edu/uscode/text/8/1255","subs":["(i)(1)(B)(ii)","(i)(1)(C)"],"by":{"0":"7, 7"}},{"t":"usc","label":"8 U.S.C. § 1324","url":"https://www.law.cornell.edu/uscode/text/8/1324","subs":["(a)","(a)(1)","(a)(1)(A)","(a)(1)(A)(i)","(a)(1)(A)(iv)","(a)(1)(A)(v)(II)","(a)(1)(B)","(a)(1)(B)(i)","(a)(1)(B)(ii)","(a)(4)(1952)","(a)(1)(A)(ii)","(a)(1)(A)(iii)","(a)(1)(A)(v)"],"stext":{"head":"§1324. Bringing in and harboring certain aliens","paras":[[0,"(a) Criminal penalties"],[0,"(1)(A) Any person who—"],[1,"(i) knowing that a person is an alien, brings to or attempts to bring to the United States in any manner whatsoever such person at a place other than a designated port of entry or place other than as designated by the Commissioner, regardless of whether such alien has received prior official authorization to come to, enter, or reside in the United States and regardless of any future official action which may be taken with respect to such alien;"],[1,"(ii) knowing or in reckless disregard of the fact that an alien has come to, entered, or remains in the United States in violation of law, transports, or moves or attempts to transport or move such alien within the United States by means of transportation or otherwise, in furtherance of such violation of law;"],[1,"(iii) knowing or in reckless disregard of the fact that an alien has come to, entered, or remains in the United States in violation of law, conceals, harbors, or shields from detection, or attempts to conceal, harbor, or shield from detection, such alien in any place, including any building or any means of transportation;"],[1,"(iv) encourages or induces an alien to come to, enter, or reside in the United States, knowing or in reckless disregard of the fact that such coming to, entry, or residence is or will be in violation of law; or"],[1,"(v)(I) engages in any conspiracy to commit any of the preceding acts, or"],[1,"(II) aids or abets the commission of any of the preceding acts,"],[0,"shall be punished as provided in subparagraph (B)."],[0,"(B) A person who violates subparagraph (A) shall, for each alien in respect to whom such a violation occurs—"],[1,"(i) in the case of a violation of subparagraph (A)(i) or (v)(I) or in the case of a violation of subparagraph (A)(ii), (iii), or (iv) in which the offense was done for the purpose of commercial advantage or private financial gain, be fined under title 18, imprisoned not more than 10 years, or both;"],[1,"(ii) in the case of a violation of subparagraph (A)(ii), (iii), (iv), or (v)(II), be fined under title 18, imprisoned not more than 5 years, or both;"],[1,"(iii) in the case of a violation of subparagraph (A)(i), (ii), (iii), (iv), or (v) during and in relation to which the person causes serious bodily injury (as defined in section 1365 of title 18) to, or places in jeopardy the life of, any person, be fined under title 18, imprisoned not more than 20 years, or both; and"],[1,"(iv) in the case of a violation of subparagraph (A)(i), (ii), (iii), (iv), or (v) resulting in the death of any person, be punished by death or imprisoned for any term of years or for life, fined under title 18, or both."],[0,"(C) It is not a violation of clauses 1 (ii) or (iii) of subparagraph (A), or of clause (iv) of subparagraph (A) except where a person encourages or induces an alien to come to or enter the United States, for a religious denomination having a bona fide nonprofit, religious organization in the United States, or the agents or officers of such denomination or organization, to encourage, invite, call, allow, or enable an alien who is present in the United States to perform the vocation of a minister or missionary for the denomination or organization in the United States as a volunteer who is not compensated as an employee, notwithstanding the provision of room, board, travel, medical assistance, and other basic living expenses, provided the minister or missionary has been a member of the denomination for at least one year."],[0,"(2) Any person who, knowing or in reckless disregard of the fact that an alien has not received prior official authorization to come to, enter, or reside in the United States, brings to or attempts to bring to the United States in any manner whatsoever, such alien, regardless of any official action which may later be taken with respect to such alien shall, for each alien in respect to whom a violation of this paragraph occurs—"],[1,"(A) be fined in accordance with title 18 or imprisoned not more than one year, or both; or"],[1,"(B) in the case of—"],[2,"(i) an offense committed with the intent or with reason to believe that the alien unlawfully brought into the United States will commit an offense against the United States or any State punishable by imprisonment for more than 1 year,"],[2,"(ii) an offense done for the purpose of commercial advantage or private financial gain, or"],[2,"(iii) an offense in which the alien is not upon arrival immediately brought and presented to an appropriate immigration officer at a designated port of entry,"],[1,"be fined under title 18 and shall be imprisoned, in the case of a first or second violation of subparagraph (B)(iii), not more than 10 years, in the case of a first or second violation of subparagraph (B)(i) or (B)(ii), not less than 3 nor more than 10 years, and for any other violation, not less than 5 nor more than 15 years."],[0,"(3)(A) Any person who, during any 12-month period, knowingly hires for employment at least 10 individuals with actual knowledge that the individuals are aliens described in subparagraph (B) shall be fined under title 18 or imprisoned for not more than 5 years, or both."],[0,"(B) An alien described in this subparagraph is an alien who—"],[1,"(i) is an unauthorized alien (as defined in section 1324a(h)(3) of this title), and"],[1,"(ii) has been brought into the United States in violation of this subsection."],[0,"(4) In the case of a person who has brought aliens into the United States in violation of this subsection, the sentence otherwise provided for may be increased by up to 10 years if—"],[1,"(A) the offense was part of an ongoing commercial organization or enterprise;"],[1,"(B) aliens were transported in groups of 10 or more; and"],[1,"(C)(i) aliens were transported in a manner that endangered their lives; or"],[1,"(ii) the aliens presented a life-threatening health risk to people in the United States."],[0,"(b) Seizure and forfeiture"],[0,"(1) In general"],[1,"Any conveyance, including any vessel, vehicle, or aircraft, that has been or is being used in the commission of a violation of subsection (a), the gross proceeds of such violation, and any property traceable to such conveyance or proceeds, shall be seized and subject to forfeiture."],[0,"(2) Applicable procedures"],[1,"Seizures and forfeitures under this subsection shall be governed by the provisions of chapter 46 of title 18 relating to civil forfeitures, including section 981(d) of such title, except that such duties as are imposed upon the Secretary of the Treasury under the customs laws described in that section shall be performed by such officers, agents, and other persons as may be designated for that purpose by the Attorney General."],[0,"(3) Prima facie evidence in determinations of violations"],[1,"In determining whether a violation of subsection (a) has occurred, any of the following shall be prima facie evidence that an alien involved in the alleged violation had not received prior official authorization to come to, enter, or reside in the United States or that such alien had come to, entered, or remained in the United States in violation of law:"],[2,"(A) Records of any judicial or administrative proceeding in which that alien's status was an issue and in which it was determined that the alien had not received prior official authorization to come to, enter, or reside in the United States or that such alien had come to, entered, or remained in the United States in violation of law."],[2,"(B) Official records of the Service or of the Department of State showing that the alien had not received prior official authorization to come to, enter, or reside in the United States or that such alien had come to, entered, or remained in the United States in violation of law."],[2,"(C) Testimony, by an immigration officer having personal knowledge of the facts concerning that alien's status, that the alien had not received prior official authorization to come to, enter, or reside in the United States or that such alien had come to, entered, or remained in the United States in violation of law."],[0,"(c) Authority to arrest"],[0,"No officer or person shall have authority to make any arrests for a violation of any provision of this section except officers and employees of the Service designated by the Attorney General, either individually or as a member of a class, and all other officers whose duty it is to enforce criminal laws."],[0,"(d) Admissibility of videotaped witness testimony"],[0,"Notwithstanding any provision of the Federal Rules of Evidence, the videotaped (or otherwise audiovisually preserved) deposition of a witness to a violation of subsection (a) who has been deported or otherwise expelled from the United States, or is otherwise unable to testify, may be admitted into evidence in an action brought for that violation if the witness was available for cross examination and the deposition otherwise complies with the Federal Rules of Evidence."],[0,"(e) Outreach program"],[0,"The Secretary of Homeland Security, in consultation with the Attorney General and the Secretary of State, as appropriate, shall develop and implement an outreach program to educate the public in the United States and abroad about the penalties for bringing in and harboring aliens in violation of this section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1324?type=usc&year=mostrecent&link-type=html"},"op":9,"head":"§1324. Bringing in and harboring certain aliens","tname":"Aliens and Nationality","by":{"0":"6, 6, 6, 6, 6, 6, 6, 6, 6, 6, 6","2":"5, 6, 7, 5, 5, 7, passim, 7, 7, 16"}},{"t":"law","label":"Pub. L. No. 99-603","url":"https://www.govinfo.gov/link/statute/100/3359","by":{"0":"6","1":"32","2":"7"}},{"t":"usc","label":"8 U.S.C. § 142","url":"https://www.law.cornell.edu/uscode/text/8/142","subs":["(1946)"],"by":{"0":"24"}},{"t":"usc","label":"15 U.S.C. § 78ff","url":"https://www.law.cornell.edu/uscode/text/15/78ff","subs":["(a)"],"by":{"0":"44"}},{"t":"usc","label":"18 U.S.C. § 2","url":"https://www.law.cornell.edu/uscode/text/18/2","subs":["(a)"],"stext":{"head":"§2. Principals","paras":[[0,"(a) Whoever commits an offense against the United States or aids, abets, counsels, commands, induces or procures its commission, is punishable as a principal."],[0,"(b) Whoever willfully causes an act to be done which if directly performed by him or another would be an offense against the United States, is punishable as a principal."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/2?type=usc&year=mostrecent&link-type=html"},"head":"§2. Principals","tname":"Crimes and Criminal Procedure","by":{"0":"39","2":"2"}},{"t":"usc","label":"18 U.S.C. § 373","url":"https://www.law.cornell.edu/uscode/text/18/373","subs":["(a)"],"stext":{"head":"§373. Solicitation to commit a crime of violence","paras":[[0,"(a) Whoever, with intent that another person engage in conduct constituting a felony that has as an element the use, attempted use, or threatened use of physical force against property or against the person of another in violation of the laws of the United States, and under circumstances strongly corroborative of that intent, solicits, commands, induces, or otherwise endeavors to persuade such other person to engage in such conduct, shall be imprisoned not more than one-half the maximum term of imprisonment or (notwithstanding section 3571) fined not more than one-half of the maximum fine prescribed for the punishment of the crime solicited, or both; or if the crime solicited is punishable by life imprisonment or death, shall be imprisoned for not more than twenty years."],[0,"(b) It is an affirmative defense to a prosecution under this section that, under circumstances manifesting a voluntary and complete renunciation of his criminal intent, the defendant prevented the commission of the crime solicited. A renunciation is not \"voluntary and complete\" if it is motivated in whole or in part by a decision to postpone the commission of the crime until another time or to substitute another victim or another but similar objective. If the defendant raises the affirmative defense at trial, the defendant has the burden of proving the defense by a preponderance of the evidence."],[0,"(c) It is not a defense to a prosecution under this section that the person solicited could not be convicted of the crime because he lacked the state of mind required for its commission, because he was incompetent or irresponsible, or because he is immune from prosecution or is not subject to prosecution."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/373?type=usc&year=mostrecent&link-type=html"},"head":"§373. Solicitation to commit a crime of violence","tname":"Crimes and Criminal Procedure","by":{"0":"39","1":"20, 30"}},{"t":"usc","label":"18 U.S.C. § 704","url":"https://www.law.cornell.edu/uscode/text/18/704","subs":["(b)(2006)","(c)(2006)"],"by":{"0":"39, 39"}},{"t":"usc","label":"18 U.S.C. § 1341","url":"https://www.law.cornell.edu/uscode/text/18/1341","subs":["(2006)"],"stext":{"head":"§1341. Frauds and swindles","paras":[[0,"Whoever, having devised or intending to devise any scheme or artifice to defraud, or for obtaining money or property by means of false or fraudulent pretenses, representations, or promises, or to sell, dispose of, loan, exchange, alter, give away, distribute, supply, or furnish or procure for unlawful use any counterfeit or spurious coin, obligation, security, or other article, or anything represented to be or intimated or held out to be such counterfeit or spurious article, for the purpose of executing such scheme or artifice or attempting so to do, places in any post office or authorized depository for mail matter, any matter or thing whatever to be sent or delivered by the Postal Service, or deposits or causes to be deposited any matter or thing whatever to be sent or delivered by any private or commercial interstate carrier, or takes or receives therefrom, any such matter or thing, or knowingly causes to be delivered by mail or such carrier according to the direction thereon, or at the place at which it is directed to be delivered by the person to whom it is addressed, any such matter or thing, shall be fined under this title or imprisoned not more than 20 years, or both. If the violation occurs in relation to, or involving any benefit authorized, transported, transmitted, transferred, disbursed, or paid in connection with, a presidentially declared major disaster or emergency (as those terms are defined in section 102 of the Robert T. Stafford Disaster Relief and Emergency Assistance Act (42 U.S.C. 5122)), or affects a financial institution, such person shall be fined not more than $1,000,000 or imprisoned not more than 30 years, or both."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1341?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1341. Frauds and swindles","tname":"Crimes and Criminal Procedure","by":{"0":"4, 9, 38","2":"6"}},{"t":"usc","label":"18 U.S.C. § 2252A","url":"https://www.law.cornell.edu/uscode/text/18/2252A","subs":["(a)(3)(B)(2006)"],"by":{"0":"27"}},{"t":"usc","label":"26 U.S.C. § 7201","url":"https://www.law.cornell.edu/uscode/text/26/7201","by":{"0":"44"}},{"t":"usc","label":"26 U.S.C. § 7206","url":"https://www.law.cornell.edu/uscode/text/26/7206","subs":["(1)"],"stext":{"head":"§7206. Fraud and false statements","paras":[[0,"Any person who—"],[0,"(1) Declaration under penalties of perjury"],[1,"Willfully makes and subscribes any return, statement, or other document, which contains or is verified by a written declaration that it is made under the penalties of perjury, and which he does not believe to be true and correct as to every material matter; or"],[0,"(2) Aid or assistance"],[1,"Willfully aids or assists in, or procures, counsels, or advises the preparation or presentation under, or in connection with any matter arising under, the internal revenue laws, of a return, affidavit, claim, or other document, which is fraudulent or is false as to any material matter, whether or not such falsity or fraud is with the knowledge or consent of the person authorized or required to present such return, affidavit, claim, or document; or"],[0,"(3) Fraudulent bonds, permits, and entries"],[1,"Simulates or falsely or fraudulently executes or signs any bond, permit, entry, or other document required by the provisions of the internal revenue laws, or by any regulation made in pursuance thereof, or procures the same to be falsely or fraudulently executed, or advises, aids in, or connives at such execution thereof; or"],[0,"(4) Removal or concealment with intent to defraud"],[1,"Removes, deposits, or conceals, or is concerned in removing, depositing, or concealing, any goods or commodities for or in respect whereof any tax is or shall be imposed, or any property upon which levy is authorized by section 6331, with intent to evade or defeat the assessment or collection of any tax imposed by this title; or"],[0,"(5) Compromises and closing agreements"],[1,"In connection with any compromise under section 7122, or offer of such compromise, or in connection with any closing agreement under section 7121, or offer to enter into any such agreement, willfully—"],[0,"(A) Concealment of property"],[2,"Conceals from any officer or employee of the United States any property belonging to the estate of a taxpayer or other person liable in respect of the tax, or"],[0,"(B) Withholding, falsifying, and destroying records"],[2,"Receives, withholds, destroys, mutilates, or falsifies any book, document, or record, or makes any false statement, relating to the estate or financial condition of the taxpayer or other person liable in respect of the tax;"],[0,"shall be guilty of a felony and, upon conviction thereof, shall be fined not more than $100,000 ($500,000 in the case of a corporation), or imprisoned not more than 3 years, or both, together with the costs of prosecution."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/7206?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§7206. Fraud and false statements","tname":"Internal Revenue Code","by":{"0":"4, 9"}},{"t":"usc","label":"29 U.S.C. § 158","url":"https://www.law.cornell.edu/uscode/text/29/158","subs":["(b)(4)"],"by":{"0":"42"}},{"t":"case","label":"Abuelhawa v. United States","cite":"556 U.S. 816","y":2009,"id":"2008/08-192","sc":1,"sum":"The Court found that using a telephone to make a misdemeanor drug purchase does not facilitate the felony of drug distribution.","sumSrc":"Oyez","by":{"1":"30"}},{"t":"case","label":"Arizona v. United States","cite":"567 U.S. 387","y":2012,"id":"2011/11-182","sc":1,"sum":"The Court found that Arizona's state immigration provisions conflicted in part with federal immigration laws.","sumSrc":"Oyez","by":{"1":"4"}},{"t":"case","label":"Ashcroft v. ACLU","cite":"542 U.S. 656","y":2004,"id":"2003/03-218","sc":1,"op":1,"sum":"In an interesting 5-to-4 vote, with Justices Kennedy, Stevens, Souter, Thomas and Ginsburg on one side and Chief Justice Rehnquist and Justices Scalia, Breyer and O'Connor on the other, the Court found that Congress had not yet met its burden to show that the COPA requirements were more effective than other methods of preventing minors.","sumSrc":"Oyez","by":{"1":"47"}},{"t":"case","label":"Board of Airport Commissioners of Los Angeles v. Jews for Jesus, Inc.","cite":"482 U.S. 569","y":1987,"id":"1986/86-104","sc":1,"op":1,"sum":"Using the \"First Amendment overbreadth doctrine,\" which allows an individual to challenge a statute on its face which is potentially threatening to others, the Court found that the ordinance violated the Constitution.","sumSrc":"Oyez","by":{"1":"38"}},{"t":"case","label":"Board of Trustees of State University of New York v. Fox","cite":"492 U.S. 469","y":1989,"id":"1988/87-2013","sc":1,"sum":"Resolution 66-156 of the State University of New York (SUNY) prohibits private commercial enterprises from operating in SUNY facilities. After the resolution was applied by campus police to bar American Future Systems, Inc. (AFS), from demonstrating and selling its housewares at a party hosted in a student dormitory, respondent Fox and other students sued for a declaratory judgment that such action violated the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"42"}},{"t":"case","label":"Brandenburg v. Ohio","cite":"395 U.S. 444","y":1969,"id":"1968/492","sc":1,"ar":5,"sum":"The Court held that a Ku Klux Klan's First Amendment rights were violated by an Ohio criminal syndicalism law.","sumSrc":"Oyez","by":{"1":"12"}},{"t":"case","label":"Brown v. Entertainment Merchants Ass’n","cite":"564 U.S. 786","y":2011,"id":"2010/08-1448","sc":1,"sum":"The Court held that video games, including violent ones, are protected speech under the First Amendment.","sumSrc":"Oyez","by":{"1":"43"}},{"t":"case","label":"Citizens United v. FEC","cite":"558 U.S. 310","y":2010,"id":"2008/08-205","sc":1,"op":1,"sum":"The Court held that corporate funding of independent political broadcasts in elections cannot be limited under the First Amendment.","sumSrc":"Oyez","by":{"1":"46"}},{"t":"case","label":"City of Chicago v. Morales","cite":"527 U.S. 41","y":1999,"id":"1998/97-1121","sc":1,"op":1,"sum":"The Court held that Chicago's Gang Congregation Ordinance was unconstitutionally vague and provided law enforcement officials too much discretion to decide what activities constitute loitering.","sumSrc":"Oyez","by":{"1":"48"}},{"t":"case","label":"Clinton v. City of New York","cite":"524 U.S. 417","y":1998,"id":"1997/97-1374","sc":1,"sum":"A case in which the Court declared that pieces of legislation passed by both houses of Congress must be either passed or vetoed as a whole, not in separate parts.","sumSrc":"Oyez","by":{"1":"23"}},{"t":"case","label":"Coates v. City of Cincinnati","cite":"402 U.S. 611","y":1971,"id":"1970/117","sc":1,"ar":3,"sum":"Cincinnati, Ohio, ordinance making it a criminal offense for \"three or more persons to assemble... on any of the sidewalks... and there conduct themselves in a manner annoying to persons passing by...,\" which has not been narrowed by any construction of the Ohio Supreme Court, held violative on its face of the due process standard of vagueness and the constitutional right of free assembly and association. Pp. …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"48, 49"}},{"t":"case","label":"Corley v. United States","cite":"556 U.S. 303","y":2009,"id":"2008/07-10441","sc":1,"sum":"The Court found that voluntary confessions made more than six hours after arrest before the person has been presented before judicial officers are inadmissible.","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"Edward J. DeBartolo Corp. v. Florida Gulf Coast Building & Construction Trades Council","cite":"485 U.S. 568","y":1988,"id":"1987/86-1461","sc":1,"ar":1,"sum":"The Court of Appeals did not err in construing § 8(b)(4) as not reaching respondent's handbilling. That construction makes it unnecessary to pass upon the serious First Amendment questions that would be raised by the Board's interpretation.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"39"}},{"t":"case","label":"Gomez v. United States","cite":"490 U.S. 858","y":1989,"id":"1988/88-5014","sc":1,"sum":"A Magistrate assigned by the District Judge conducted the voir dire examination and jury selection for petitioners' trial on multiple felony counts. The judge overruled petitioners' objections to the assignment of the Magistrate. The judge offered to review any of the Magistrate's rulings de novo, but petitioners registered no specific challenge to the selection of any juror. After petitioners were convicted and …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"33"}},{"t":"case","label":"Gooding v. Wilson","cite":"405 U.S. 518","y":1972,"id":"1971/70-26","sc":1,"sum":"The Supreme Court held that the Georgia statute was unconstitutional. With Justice William J. Brennan writing for the majority, the Court reasoned that the statute was unconstitutionally vague and overbroad. Quoting Speiser v. Randall , the Court noted that \"the separation of legitimate from illegitimate speech calls for more sensitive tools than (Georgia) has supplied.\" Chief Justice Warren E. Burger dissented.","sumSrc":"Oyez","by":{"1":"16, 40"}},{"t":"case","label":"Page(s) Grayned v. City of Rockford","cite":"408 U.S. 104","y":1972,"id":"1971/70-5106","sc":1,"sum":"1. Antipicketing ordinance, virtually identical with one invalidated as violative of equal protection in Police Department of Chicago v. Mosley, ante, p. 92, is likewise invalid.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"48"}},{"t":"case","label":"Henson v. Santander Consumer USA Inc.","cite":"137 S. Ct. 1718","y":2017,"id":"2016/16-349","sc":1,"sum":"The Court determined that a party that purchases a debt and attempts to collect the debt for its own account is not a “debt collector” subject to the Fair Debt Collection Practices Act (FDCPA).","sumSrc":"Oyez","by":{"1":"19, 22"}},{"t":"case","label":"Holder v. Humanitarian Law Project","cite":"561 U.S. 1","y":2010,"id":"2009/08-1498","sc":1,"op":1,"sum":"The Court held that sections of the Antiterrorism and Effective Death Penalty Act were not unconstitutionally vague in a lawsuit that named the Kurdistan Workers Party and Liberation Tigers of Tamil Eelam.","sumSrc":"Oyez","by":{"1":"38, 44, 50"}},{"t":"case","label":"Iancu v. Brunetti","cite":"139 S. Ct. 2294","y":2019,"id":"2018/18-302","sc":1,"sum":"The Lanham Act prohibition on the registration of “immoral” or “scandalous” trademarks infringes the First Amendment.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"43"}},{"t":"case","label":"Jennings v. Rodriguez","cite":"138 S. Ct. 830","y":2018,"id":"2017/15-1204","sc":1,"op":3,"sum":"The Court held that non-citizens who are subject to mandatory detention under the Immigration and Nationality Act are not entitled to periodic bond hearings. with the possibility of release if they are detained for longer than six months.","sumSrc":"Oyez","by":{"1":"33"}},{"t":"case","label":"Johnson v. United States","cite":"135 S. Ct. 2551","y":2015,"id":"2014/13-7120","sc":1,"sum":"The Court determined that the residual clause of the Armed Criminal Career Act is unconstitutionally vague.","sumSrc":"Oyez","by":{"1":"51"}},{"t":"case","label":"Legal Services Corp. v. Velazquez","cite":"531 U.S. 533","y":2001,"id":"2000/99-603","sc":1,"sum":"The Court held that the funding provision that limited arguments legal services attorneys were allowed to make on behalf of indigent welfare claimants violated the First Amendment by regulating private speech and insulating federal law from legitimate judicial challenge.","sumSrc":"Oyez","by":{"1":"35"}},{"t":"case","label":"Matal v. Tam","cite":"137 S. Ct. 1744","y":2017,"id":"2016/15-1293","sc":1,"sum":"The Court determined that the Disparagement Clause prohibits trademarks that disparage the members of a racial or ethnic group and violates the Free Speech Clause of the First Amendment.","sumSrc":"Oyez","by":{"1":"44, 47"}},{"t":"case","label":"Murdock v. Pennsylvania","cite":"319 U.S. 105","y":1943,"id":"1940-1955/319us105","sc":1,"sum":"The Court held that it was unconstitutional for a state to require solicitors to obtain a license that amounted to a tax on religious activities.","sumSrc":"Oyez","by":{"1":"42"}},{"t":"case","label":"National Institute of Family & Life Advocates v. Becerra","cite":"138 S. Ct. 2361","y":2018,"id":"2017/16-1140","sc":1,"op":1,"sum":"The Court decided that pro-life pregnancy center petitioners were likely to succeed on their claim that the California Reproductive Freedom, Accountability, Comprehensive Care, and Transparency Act violated the First Amendment.","sumSrc":"Oyez","by":{"1":"42"}},{"t":"case","label":"NLRB v. SW General, Inc.","cite":"137 S. Ct. 929","y":2017,"id":"2016/15-1251","sc":1,"sum":"The Court determined that the limitations on nominees to vacant positions serving in an acting capacity under the Federal Vacancies Reform Act apply equally to first assistants who take on the position and to those who are selected by the President from within the same agency or from another agency.","sumSrc":"Oyez","by":{"1":"31"}},{"t":"case","label":"R.A.V. v. City of St. Paul","cite":"505 U.S. 377","y":1992,"id":"1991/90-7675","sc":1,"sum":"The Court found a Minnesota ordinance violated the First Amendment because the ordinance was overly broad in the content-based speech it prohibited.","sumSrc":"Oyez","by":{"1":"45, 46","2":"22"}},{"t":"case","label":"Reno v. ACLU","cite":"521 U.S. 844","y":1997,"id":"1996/96-511","sc":1,"sum":"The Court ruled that certain provisions of the Communications Decency Act concerning \"indecent\" behavior were unconstitutionally vague.","sumSrc":"Oyez","by":{"1":"19, 36, 38"}},{"t":"case","label":"Rosenberger v. Rector & Visitors of University of Virginia","cite":"515 U.S. 819","y":1995,"id":"1994/94-329","sc":1,"sum":"The Court, in a 5-to-4 opinion, held that the University's denial of funding to Rosenberger, due to the content of his message, imposed a financial burden on his speech and amounted to viewpoint discrimination. The Court noted that no matter how scarce University publication funding may be, if it chooses to promote speech at all, it must promote all forms of it equally.","sumSrc":"Oyez","by":{"1":"44"}},{"t":"case","label":"Sebelius v. Cloer","cite":"569 U.S. 369","y":2013,"id":"2012/12-236","sc":1,"sum":"The Court found that a person who petitions under the National Childhood Vaccine Injury Act can recover attorney's fees regardless of if the petition was ultimately successful.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"case","label":"Sessions v. Dimaya","cite":"138 S. Ct. 1204","y":2018,"id":"2017/15-1498","sc":1,"sum":"A case in which the Court struck down the Immigration and Nationality Act’s “crime of violence” provision as unconstitutionally vague in violation of the Due Process Clause of the Fifth Amendment.","sumSrc":"Oyez","by":{"1":"51"}},{"t":"case","label":"Smith v. Goguen","cite":"415 U.S. 566","y":1974,"id":"1973/72-1254","sc":1,"sum":"Appellee, for wearing a small United States flag sewn to the seat of his trousers, was convicted of violating the provision of the Massachusetts flag-misuse statute that subjects to criminal liability anyone who \"publicly.. treats contemptuously' the flag of the United States....\" The Massachusetts. Supreme Judicial Court affirmed. The District Court in appellee's habeas -corpus action found the \"treats …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"51"}},{"t":"case","label":"Stone v. INS","cite":"514 U.S. 386","y":1995,"id":"1994/93-1199","sc":1,"sum":"A timely motion for reconsideration of a BIA decision does not toll the running of § 106(a)(1)'s 90-day period.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"33"}},{"t":"case","label":"Timbs v. Indiana","cite":"139 S. Ct. 690","y":2019,"id":"2018/17-1091","sc":1,"sum":"The Eighth Amendment’s Excessive Fines Clause is an incorporated protection applicable to the States under the Fourteenth Amendment’s Due Process Clause.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"50"}},{"t":"case","label":"United States v. Davis","cite":"139 S. Ct. 2319","y":2019,"id":"2018/18-431","sc":1,"sum":"Title 18 U. S. C. §924(c)(3)(B), which provides enhanced penalties for using a firearm during a “crime of violence,” is unconstitutionally vague.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"47"}},{"t":"case","label":"United States v. Kim","cite":"193 F.3d 567","y":1999,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/193/567/","by":{"1":"24"}},{"t":"case","label":"United States v. Kozminski","cite":"487 U.S. 931","y":1988,"id":"1987/86-2000","sc":1,"sum":"The Court held that precedent had established that the type of involuntary servitude prohibited by the Thirteenth Amendment is limited to that “enforced by the use or threatened use of physical or legal coercion.” Involuntary servitude had never before been extended to cover labor compelled by the use of psychological coercion.","sumSrc":"Oyez","by":{"1":"49"}},{"t":"case","label":"United States v. L. Cohen Grocery Co.","cite":"255 U.S. 81","y":1921,"id":"scdb/1920-161","sc":1,"sum":"1. Section 4 of the Food Control Act of August 10, 1917, as amended October 22, 1919, in denouncing and attaching a penalty of fine or imprisonment to the making by any person of “any unjust or unreasonable rate or charge in handling or dealing in or with any necessaries,” must be construed” as forbidding and penalizing the exaction of an excessive price upon the sale of a commodity.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"48, 49"}},{"t":"case","label":"United States v. Lopez","cite":"590 F.3d 1238","y":2009,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/590/1238/","by":{"1":"18","2":"10"}},{"t":"case","label":"United States v. Reese","cite":"92 U.S. 214","y":1876,"id":"1850-1900/92us214","sc":1,"sum":"The Court concluded that the relevant sections of the Enforcement Act lacked the necessary, limiting language to qualify as enforcement of the Fifteenth Amendment.","sumSrc":"Oyez","by":{"1":"48"}},{"t":"case","label":"Page(s) United States v. Royal Dutch West India Mail","cite":"250 F. 913","y":1918,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F./250/913/","by":{"1":"31, 32"}},{"t":"case","label":"United States v. Shum","cite":"496 F.3d 390","y":2007,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/496/390/","by":{"1":"24"}},{"t":"case","label":"United States v. Thum","cite":"749 F.3d 1143","y":2014,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/749/1143/","sum":"Describing the government’s interpretation as “broad”.","sumSrc":"brief:1","by":{"1":"19","2":"10"}},{"t":"case","label":"United States v. Ye","cite":"588 F.3d 411","y":2009,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/588/411/","sum":"Upholding harboring convictions for defendant who “advised [immigrant workers] they could purchase fake documents in Chicago”.","sumSrc":"brief:1","by":{"1":"24"}},{"t":"case","label":"Village of Hoffman Estates v. Flipside, Hoffman Estates, Inc.","cite":"455 U.S. 489","y":1982,"id":"1981/80-1681","sc":1,"sum":"The ordinance is not facially overbroad or vague but is reasonably clear in its application to appellee.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"47"}},{"t":"case","label":"Watts v. United States","cite":"394 U.S. 705","y":1969,"id":"1968/1107_misc","sc":1,"sum":"The Court concluded, without hearing arguments, that Watts' statement was \"political hyperbole\". The Court noted, \"The language of the political arena… is often vituperative, abusive, and inexact.\" Thus, considering the \"context, and regarding the expressly conditional nature of the statement and the reaction of the listeners,\" the Court ruled that Watts' statement was not a true threat.","sumSrc":"Oyez","by":{"1":"40"}},{"t":"case","label":"Yates v. United States","cite":"135 S. Ct. 1074","y":2015,"id":"2014/13-7451","sc":1,"ar":1,"sum":"The Court ruled that a “tangible item” as defined by Section 1519 of the Sarbanes-Oxley Act is one used to record or preserve information.","sumSrc":"Oyez","by":{"1":"20"}},{"t":"const","label":"Amendment I","clauses":[["establishment","Establishment Clause"],["free-exercise","Free Exercise Clause"],["free-speech","Free Speech Clause"],["free-press","Free Press Clause"],["assembly-petition","Assembly, Petition and Association"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"1":"16","2":"passim"}},{"t":"usc","label":"8 U.S.C. § 144","url":"https://www.law.cornell.edu/uscode/text/8/144","subs":["(1946)"],"by":{"1":"32"}},{"t":"law","label":"Immigration and Nationality Act, Pub. L. No. 82-414","url":"https://www.govinfo.gov/link/statute/66/163","by":{"1":"32"}},{"t":"case","label":"Boos v. Barry","cite":"485 U.S. 312","y":1988,"id":"1987/86-803","sc":1,"sum":"The Court found that the Code's restriction on sign displays violated the First Amendment while the ban on congregations did not. First, Justice O'Connor argued that the prohibition on signs failed to meet the high standards that the Court uses when evaluating the content-based regulation of political speech in a public forum.","sumSrc":"Oyez","by":{"2":"8"}},{"t":"case","label":"Broadrick v. Oklahoma","cite":"413 U.S. 601","y":1973,"id":"1972/71-1639","sc":1,"op":5,"sum":"Section 818 of the Oklahoma statute is not unconstitutional on its face. CSC v. Letter Carriers, ante, p. 548.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"8"}},{"t":"case","label":"Bryan v. United States","cite":"524 U.S. 184","y":1998,"id":"1997/96-8422","sc":1,"sum":"The Court held that the term \"willfully\" in section 924(a)(1)(D) requires proof only that the defendant knew his conduct was unlawful, not that he also knew of the federal licensing requirement.","sumSrc":"Oyez","by":{"2":"11"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"sum":"The Court held that, on its face, RLUIPA made an accommodation allowed by the First Amendment. The Court reasoned that the law was an effort to alleviate the \"government-created burden\" on religious exercise that prisoners faced. Nor did section three discriminate between mainstream and non-mainstream religions.","sumSrc":"Oyez","by":{"2":"20"}},{"t":"case","label":"DelRio-Mocci v. Connolly Props. Inc.","cite":"672 F.3d 241","y":2012,"url":"https://www.courtlistener.com/c/F.3d/672/241/","sum":"Construing Section 1324(a)(1)(A)(iv) to prohibit “an affirmative act that substantially encourages or induces an alien lacking lawful immigration status to come to, enter, or reside in the United States where the undocumented person otherwise might not have done so”.","sumSrc":"brief:2","by":{"2":"13"}},{"t":"case","label":"Duncan v. Walker","cite":"533 U.S. 167","y":2001,"id":"2000/00-121","sc":1,"sum":"The Court held that an federal habeas corpus petition is not an \"application for State post-conviction or other collateral review\" within the meaning of 28 USC section 2244(d)(2). \"Section 2244(d)(2) therefore did not toll the limitation period during the pendency of [Walker's] first federal habeas petition,\" wrote Justice O'Connor. \"[I]f the statute were construed so as to give applications for federal review the same tolling effect as applications for state collateral review, then [section] 2244(d)(2) would furnish little incentive for individuals to seek relief from the state courts before filing federal habeas petitions,\" concluded Justice O'Connor.","sumSrc":"Oyez","by":{"2":"4"}},{"t":"case","label":"Maracich v. Spears","cite":"570 U.S. 48","y":2013,"id":"2012/12-25","sc":1,"sum":"The Court found that lawyers may use personal information protected by the Driver's Privacy Protection Act to find potential plaintiffs for a group action.","sumSrc":"Oyez","by":{"2":"2"}},{"t":"case","label":"(I) Cases—Continued: Milavetz, Gallop & Milavetz, P. A. v. United States","cite":"559 U.S. 229","y":2010,"id":"2009/08-1119","sc":1,"sum":"The Court held that attorneys who provide bankruptcy assistance are debt relief agencies under the Bankruptcy Abuse Prevention and Consumer Protection Act.","sumSrc":"Oyez","by":{"2":"3, 15"}},{"t":"case","label":"Star Athletica , L.L.C. v. Varsity Brands, Inc.","cite":"137 S. Ct. 1002","y":2017,"id":"2016/15-866","sc":1,"sum":"The Court determined that the test for deciding whether a feature of a “useful article” is copyrightable under the Copyright Act is whether the feature can be perceived as a two- or three-dimensional artwork that is separable from the useful article and if it would be a protectable pictorial, graphical, or sculptural work on its own.","sumSrc":"Oyez","by":{"2":"5"}},{"t":"case","label":"Susan B. Anthony List v. Driehaus","cite":"573 U.S. 149","y":2014,"id":"2013/13-193","sc":1,"sum":"The Court held that pre-enforcement challenges are justiciable when evidence indicates that threatened enforcement of the law is sufficiently imminent.","sumSrc":"Oyez","by":{"2":"17"}},{"t":"case","label":"Taggart v. Lorenzen","cite":"139 S. Ct. 1795","y":2019,"id":"2018/18-489","sc":1,"sum":"A creditor may be held in civil contempt for violating a bankruptcy court’s discharge order if there is no fair ground of doubt as to whether the order barred the creditor’s conduct.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"3"}},{"t":"case","label":"United States v. Anderton","cite":"901 F.3d 278","y":2018,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/901/278/","sum":"Rejecting “as applied” vagueness challenge to Section 1324(a)(1)(A)(iv) on plain-error review.","sumSrc":"brief:2","by":{"2":"20"}},{"t":"case","label":"United States v. Costello","cite":"666 F.3d 1040","y":2012,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/666/1040/","by":{"2":"7"}},{"t":"case","label":"United States v. Garcia-Paulin","cite":"627 F.3d 127","y":2010,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/627/127/","by":{"2":"7"}},{"t":"case","label":"United States v. Gementera","cite":"379 F.3d 596","y":2004,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/379/596/","by":{"2":"21"}},{"t":"case","label":"United States v. Gonzalez-Rodriguez","cite":"301 Fed. Appx. 874","y":2008,"court":"11th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./301/874/","by":{"2":"10"}},{"t":"case","label":"United States v. Lanier","cite":"520 U.S. 259","y":1997,"id":"1996/95-1717","sc":1,"sum":"Authored by Justice David Souter, the Court ruled that the standard of notice that the Court of Appeals employed was higher than the Constitution requires and too demanding.","sumSrc":"Oyez","by":{"2":"23"}},{"t":"case","label":"United States Nat’l Bank of Oregon v. Independent Ins. Agents of Am., Inc.","cite":"508 U.S. 439","y":1993,"id":"1992/92-484","sc":1,"sum":"The Act of Sept. 7, 1916, 39 Stat. 753 (1916 Act), among other things, authorized any national bank doing business in a community with a population not exceeding 5,000 to act as the agent for any insurance company. Although early editions of the United States Code included this provision as section 92 of Title 12 (section 92), the 1952 Code and subsequent editions omitted section 92 with a note indicating that …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"5"}},{"t":"case","label":"United States v. O’Brien","cite":"391 U.S. 367","y":1968,"id":"1967/232","sc":1,"sum":"The Court found that it was not an infringement on one's First Amendment rights to criminalize burning a draft card.","sumSrc":"Oyez","by":{"2":"13"}},{"t":"case","label":"United States v. Stitt","cite":"139 S. Ct. 399","y":2018,"id":"2018/17-765","sc":1,"sum":"The term “burglary” in the Armed Career Criminal Act includes burglary of a structure or vehicle that has been adapted or is customarily used for overnight accommodation.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"20"}},{"t":"usc","label":"18 U.S.C. § 48","url":"https://www.law.cornell.edu/uscode/text/18/48","subs":["(a)(2006)"],"by":{"2":"18"}}]};